#!/usr/bin/env bash\nset -euo pipefail\n\n# Mock environment variables required by the script\nexport GITHUB_REPOSITORY="owner/repo"\nexport GITHUB_EVENT_PATH="/tmp/event.json"\nexport GITHUB_TOKEN="dummy-token"\n\n# Create a dummy event file (content not used in the script)\necho "{}" > "$GITHUB_EVENT_PATH"\n\n# Test deterministic selection with seed=1 (should pick the second phrase)\nexport INPUT_SEED=1\nexport INPUT_CUSTOM_MESSAGE=""\n\noutput=$(bash "$(dirname \"$0\")/../src/boost.sh")\nexpected_phrase="Your code is the last beacon of hope."\n\nif [[ "$output" != *"$expected_phrase"* ]]; then\n  echo "Test failed: expected phrase not found in output"\n  echo "Output: $output"\n  exit 1\nfi\n\necho "All tests passed."
